#include <zephyr/data/cobs.h>
#include <zephyr/sys/util.h>
#include <zephyr/net_buf.h>

int cobs_encode(struct net_buf *src, struct net_buf *dst, uint32_t flags)
{
	if (src == NULL || dst == NULL) {
		return -EINVAL;
	}

	if (flags & ~COBS_FLAG_TRAILING_DELIMITER) {
		return -EINVAL;
	}

	size_t max_encoded_size = cobs_max_encoded_len(src->len, flags);

	if (net_buf_tailroom(dst) < max_encoded_size) {
		return -ENOMEM;
	}

	uint8_t delimiter = COBS_CUSTOM_DELIMITER(flags);
	uint8_t *code_ptr = net_buf_add(dst, 1);
	uint8_t code = 1;

	while (src->len > 0) {
		uint8_t byte = net_buf_pull_u8(src);

		if (byte == delimiter) {
			*code_ptr = code ^ delimiter;
			code_ptr = net_buf_add(dst, 1);
			code = 1;
		} else {
			net_buf_add_u8(dst, byte);
			code++;
			if (code == 0xff) {
				*code_ptr = code ^ delimiter;
				code = 1;
				if (src->len > 0) {
					code_ptr = net_buf_add(dst, 1);
				}
			}
		}
	}

	if (code_ptr != NULL) {
		*code_ptr = code ^ delimiter;
	}

	if (flags & COBS_FLAG_TRAILING_DELIMITER) {
		net_buf_add_u8(dst, delimiter);
	}

	return 0;
}

int cobs_decode(struct net_buf *src, struct net_buf *dst, uint32_t flags)
{
	if (src == NULL || dst == NULL) {
		return -EINVAL;
	}

	if (flags & ~COBS_FLAG_TRAILING_DELIMITER) {
		return -EINVAL;
	}

	if (src->len == 0) {
		return 0;
	}

	uint8_t delimiter = COBS_CUSTOM_DELIMITER(flags);
	uint8_t code = 0xff;
	uint8_t block = 0;

	while (src->len > 0) {
		if (block > 0) {
			uint8_t byte = net_buf_pull_u8(src);

			if (byte == delimiter) {
				return -EINVAL;
			}

			if (net_buf_tailroom(dst) < 1) {
				return -ENOMEM;
			}
			net_buf_add_u8(dst, byte);
		} else {
			if (code != 0xff) {
				if (net_buf_tailroom(dst) < 1) {
					return -ENOMEM;
				}
				net_buf_add_u8(dst, delimiter);
			}

			code = net_buf_pull_u8(src) ^ delimiter;
			block = code;
			if (code == 0x00) {
				if ((flags & COBS_FLAG_TRAILING_DELIMITER) && src->len == 0) {
					break;
				}
				return -EINVAL;
			}
		}
		block--;
	}

	if ((flags & COBS_FLAG_TRAILING_DELIMITER) && code != 0x00) {
		return -EINVAL;
	}

	if (block > 0) {
		return -EINVAL;
	}

	return 0;
}
